const THREE: any = __THREE_BUNDLE__.THREE
// @ts-ignore - vendored bundle has no ambient type declarations
const RoundedBoxGeometry: any = __THREE_BUNDLE__.RoundedBoxGeometry
// @ts-ignore - vendored bundle has no ambient type declarations
const RoomEnvironment: any = __THREE_BUNDLE__.RoomEnvironment

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ResponsiveImageValue {
    src: string
    srcSet?: string
    alt?: string
}

type MarkKind = "ring" | "grid" | "wave" | "chevron" | "cross" | "dots" | "arc" | "diamond" | "hex" | "mono" | "circles" | "triangle" | "bars" | "wordmark"

interface LogoItem {
    image?: ResponsiveImageValue
    name: string
    link?: string
    logoScale: number
    colorOverride?: string
    /** Internal only - set for built-in demo content, never a buyer-facing control. */
    markKind?: MarkKind
    /** Internal only - the demo mark's own color, never a buyer-facing control. */
    markColor?: string
}

type QualityMode = "auto" | "high" | "performance"

interface LogoCubesProps {
    logos: LogoItem[]
    cubeColor: string
    cornerRadius: number
    roughness: number
    clearcoat: number
    logoScaleDefault: number
    spread: number
    depth: number
    density: number
    randomness: number
    seed: number
    hover: boolean
    hoverLift: number
    hoverTilt: number
    hoverScale: number
    pointerParallax: boolean
    showFloor: boolean
    floorColor: string
    transparentBackground: boolean
    backgroundColor: string
    cameraDistance: number
    cameraElevation: number
    lightingIntensity: number
    shadowStrength: number
    quality: QualityMode
    mobileScale: number
    mobileQuality: QualityMode
    style?: CSSProperties
}

// ---------------------------------------------------------------------------
// Deterministic arrangement (no physics engine)
// ---------------------------------------------------------------------------

function mulberry32(seed: number) {
    let a = seed | 0
    return function random() {
        a = (a + 0x6d2b79f5) | 0
        let t = Math.imul(a ^ (a >>> 15), 1 | a)
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296
    }
}

interface PlacedCube {
    x: number
    y: number
    z: number
    topY: number
    yaw: number
    tiltX: number
    tiltZ: number
    supportDepth: number
    role: "hero" | "grounded" | "leaning" | "edge"
}

const CUBE_SIZE = 1
const FOOTPRINT_R = CUBE_SIZE * 0.62
const CAMERA_AZIMUTH = Math.PI * (28 / 180)

const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5)) // ~137.5 degrees

// Corners of a unit cube (half-size 0.5) - reused to find how a rotated
// cube actually rests under "gravity" instead of assuming a fixed height,
// so tilted/leaning cubes never float above or sink through their support.
const UNIT_CORNERS: [number, number, number][] = []
for (const cx of [-0.5, 0.5])
    for (const cy of [-0.5, 0.5]) for (const cz of [-0.5, 0.5]) UNIT_CORNERS.push([cx, cy, cz])

function localYExtent(q: any): { min: number; max: number } {
    let min = Infinity
    let max = -Infinity
    const v = new THREE.Vector3()
    for (const [cx, cy, cz] of UNIT_CORNERS) {
        v.set(cx, cy, cz).applyQuaternion(q)
        if (v.y < min) min = v.y
        if (v.y > max) max = v.y
    }
    return { min, max }
}

function buildRestQuaternion(tiltX: number, yaw: number, tiltZ: number): any {
    return new THREE.Quaternion().setFromEuler(new THREE.Euler(tiltX, yaw, tiltZ))
}

/**
 * Deterministic "art-directed randomness": a handful of premium objects
 * dropped and gathered on a studio floor, not a scatter algorithm. A small
 * number of cubes are forced into a foreground-hero role near the camera;
 * the rest draw from weighted orientation families (mostly grounded, some
 * leaning, fewer resting on an edge) so the pile reads as gravity-settled
 * rather than uniformly upright. Positions come from a tight golden-angle
 * spiral (robust on every seed) with an attract/repel pass that pulls
 * non-hero cubes into real contact with a neighbor instead of leaving even
 * gaps everywhere.
 */
function generateArrangement(
    count: number,
    seed: number,
    spread: number,
    depthCtrl: number,
    density: number,
    randomness: number
): PlacedCube[] {
    const rand = mulberry32(Math.floor(seed) || 1)
    // Broader rather than taller - the pile's mass goes outward, not up.
    const radiusX = 1.18 + spread * 1.45
    const radiusZ = (1.05 + depthCtrl * 1.25) * 0.85
    const hardMinDist = FOOTPRINT_R * 2 * 0.5
    const stackThreshold = FOOTPRINT_R * 2 * (0.5 + density * 0.5)
    const leanMax = 0.05 + randomness * 0.16

    const heroCount = count >= 16 ? 3 : count >= 6 ? 2 : count >= 3 ? 1 : 0

    // --- roles -------------------------------------------------------
    // Weighted toward grounded so most of the pile stays low and calm -
    // leaning/edge add variety without turning into a tower or a scatter.
    const roles: PlacedCube["role"][] = []
    for (let i = 0; i < count; i++) {
        if (i < heroCount) {
            roles.push("hero")
            continue
        }
        const r = rand()
        if (r < 0.5) roles.push("grounded")
        else if (r < 0.82) roles.push("leaning")
        else roles.push("edge")
    }

    // --- base positions ------------------------------------------------
    // Hero cubes: biased toward the camera-facing side of the cluster, at a
    // moderate radius, so they read as foreground objects without becoming
    // disproportionately large under perspective. Everyone else: a
    // golden-angle spiral (even angular coverage on any seed/count) with
    // center-biased radius for a dense core + looser rim. Jitter is kept
    // deliberately modest so every seed stays inside the same family of
    // shapes rather than producing structurally different compositions.
    const points: { x: number; z: number }[] = []
    let heroesPlaced = 0
    let spiralIndex = 0
    const spiralCount = count - heroCount
    for (let i = 0; i < count; i++) {
        if (roles[i] === "hero") {
            const angle = CAMERA_AZIMUTH + (rand() * 2 - 1) * 0.32 + heroesPlaced * 0.85
            const radiusFrac = 0.46 + rand() * 0.16
            points.push({ x: Math.cos(angle) * radiusFrac * radiusX, z: Math.sin(angle) * radiusFrac * radiusZ })
            heroesPlaced++
        } else {
            const denom = Math.max(1, spiralCount)
            const angle = spiralIndex * GOLDEN_ANGLE + (rand() * 2 - 1) * (0.16 + randomness * 0.34)
            const areaFrac = (spiralIndex + 0.5) / denom
            const radiusFrac = Math.pow(Math.sqrt(areaFrac), 1.4) * (1 + (rand() * 2 - 1) * randomness * 0.14)
            points.push({ x: Math.cos(angle) * radiusFrac * radiusX, z: Math.sin(angle) * radiusFrac * radiusZ })
            spiralIndex++
        }
    }
    if (count === 1) points[0] = { x: 0, z: 0 }

    // --- separate any hard overlaps ------------------------------------
    for (let pass = 0; pass < 3; pass++) {
        for (let i = 0; i < points.length; i++) {
            for (let j = i + 1; j < points.length; j++) {
                const dx = points[j].x - points[i].x
                const dz = points[j].z - points[i].z
                const d = Math.sqrt(dx * dx + dz * dz) || 0.0001
                if (d < hardMinDist) {
                    const push = (hardMinDist - d) / 2
                    const nx = dx / d
                    const nz = dz / d
                    points[i].x -= nx * push
                    points[i].z -= nz * push
                    points[j].x += nx * push
                    points[j].z += nz * push
                }
            }
        }
    }

    // --- pull every non-hero cube into real contact with a neighbor -----
    // A pure scatter leaves even gaps everywhere; a real dropped pile has
    // objects actually touching, and nothing should read as isolated.
    for (let i = 0; i < points.length; i++) {
        if (roles[i] === "hero") continue
        let nearest = -1
        let minDist = Infinity
        for (let j = 0; j < points.length; j++) {
            if (j === i) continue
            const dx = points[j].x - points[i].x
            const dz = points[j].z - points[i].z
            const d = Math.sqrt(dx * dx + dz * dz)
            if (d < minDist) {
                minDist = d
                nearest = j
            }
        }
        const targetD = hardMinDist * 1.02
        if (nearest >= 0 && minDist > targetD * 1.35) {
            const dx = points[nearest].x - points[i].x
            const dz = points[nearest].z - points[i].z
            const d = Math.sqrt(dx * dx + dz * dz) || 0.0001
            const pull = Math.min((d - targetD) * 0.55, d * 0.35)
            points[i].x += (dx / d) * pull
            points[i].z += (dz / d) * pull
        }
    }

    // --- orientation + gravity-settled height ---------------------------
    // Height variation is deliberately curated, not left to open-ended
    // stacking: a small, capped number of cubes nest into the saddle
    // between two already-placed floor neighbors (so an elevated cube is
    // always visually supported by two contact points, never perched alone
    // on a single one), biased toward the pile's center so the silhouette
    // reads as a mound - broad base, moderate peak - not a bridge or tower.
    const maxStacked = count <= 4 ? 0 : count <= 8 ? 1 : count <= 14 ? 3 : Math.round(count * 0.26)
    const centralRadius = Math.max(radiusX, radiusZ) * 0.66
    let stackedCount = 0

    const placed: PlacedCube[] = []
    for (let i = 0; i < count; i++) {
        const role = roles[i]

        let tiltX = 0
        let tiltZ = 0
        const majorSign = rand() < 0.5 ? -1 : 1
        const majorIsX = rand() < 0.5

        if (role === "hero") {
            tiltX = (rand() * 2 - 1) * leanMax * 0.35
            tiltZ = (rand() * 2 - 1) * leanMax * 0.35
        } else if (role === "grounded") {
            tiltX = (rand() * 2 - 1) * leanMax * 0.7
            tiltZ = (rand() * 2 - 1) * leanMax * 0.7
        } else if (role === "leaning") {
            // Lean biased radially outward, as if settling under its own
            // weight toward the open side of the pile rather than a random
            // wobble - reads as physically motivated rather than arbitrary.
            const outward = Math.atan2(points[i].z, points[i].x)
            const major = THREE.MathUtils.degToRad(12 + rand() * 12)
            tiltX = Math.sin(outward) * major * (0.7 + rand() * 0.3)
            tiltZ = Math.cos(outward) * major * (0.7 + rand() * 0.3)
        } else {
            // edge: one axis gets a believable "resting on an edge" tilt -
            // clearly more than a lean, but kept short of anything that
            // reads as precariously balanced or perched.
            const major = THREE.MathUtils.degToRad(24 + rand() * 12) * majorSign
            const minor = (rand() * 2 - 1) * THREE.MathUtils.degToRad(5)
            tiltX = majorIsX ? major : minor
            tiltZ = majorIsX ? minor : major
        }

        const yaw = rand() * Math.PI * 2
        const q = buildRestQuaternion(tiltX, yaw, tiltZ)
        const extent = localYExtent(q)

        // Nearby already-placed floor-resting (non-hero) cubes, nearest first.
        const floorNeighbors: { idx: number; d: number }[] = []
        for (let j = 0; j < placed.length; j++) {
            if (placed[j].role === "hero" || placed[j].supportDepth > 0) continue
            const dx = points[i].x - placed[j].x
            const dz = points[i].z - placed[j].z
            floorNeighbors.push({ idx: j, d: Math.sqrt(dx * dx + dz * dz) })
        }
        floorNeighbors.sort((a, b) => a.d - b.d)

        const distFromCenter = Math.sqrt(points[i].x * points[i].x + points[i].z * points[i].z)
        const eligible = role !== "hero" && stackedCount < maxStacked && distFromCenter < centralRadius

        let x = points[i].x
        let z = points[i].z
        let y: number
        let supportDepth = 0

        if (
            eligible &&
            floorNeighbors.length >= 2 &&
            floorNeighbors[0].d < stackThreshold &&
            floorNeighbors[1].d < stackThreshold * 1.5 &&
            rand() < 0.62
        ) {
            // Nest in the saddle between two neighbors - rests against both,
            // never floats above a single point.
            const a = placed[floorNeighbors[0].idx]
            const b = placed[floorNeighbors[1].idx]
            x = (a.x + b.x) / 2
            z = (a.z + b.z) / 2
            y = Math.max(a.y + a.topY, b.y + b.topY) - extent.min - CUBE_SIZE * 0.12
            supportDepth = 1
            stackedCount++
        } else if (eligible && floorNeighbors.length >= 1 && floorNeighbors[0].d < stackThreshold && rand() < 0.5) {
            // Only one usable neighbor - snap close to directly above it
            // rather than leaving it near its original (possibly offset)
            // spiral point, so it doesn't read as randomly floating nearby.
            const a = placed[floorNeighbors[0].idx]
            x = a.x + (points[i].x - a.x) * 0.2
            z = a.z + (points[i].z - a.z) * 0.2
            y = a.y + a.topY - extent.min - CUBE_SIZE * 0.1
            supportDepth = 1
            stackedCount++
        } else {
            y = -extent.min
        }

        placed.push({ x, y, z, topY: extent.max, yaw, tiltX, tiltZ, supportDepth, role })
    }

    // --- final guarantee: nothing sits isolated -------------------------
    // The attract pass above is probabilistic; this closes the gap
    // deterministically for every seed, at floor level and after stacking.
    for (let i = 0; i < placed.length; i++) {
        if (placed[i].role === "hero") continue
        let nearest = -1
        let minDist = Infinity
        for (let j = 0; j < placed.length; j++) {
            if (j === i) continue
            const dx = placed[i].x - placed[j].x
            const dz = placed[i].z - placed[j].z
            const d = Math.sqrt(dx * dx + dz * dz)
            if (d < minDist) {
                minDist = d
                nearest = j
            }
        }
        const isolationLimit = hardMinDist * 1.9
        if (nearest >= 0 && minDist > isolationLimit && placed[i].supportDepth === 0) {
            const dx = placed[nearest].x - placed[i].x
            const dz = placed[nearest].z - placed[i].z
            const d = Math.sqrt(dx * dx + dz * dz) || 0.0001
            const pull = d - isolationLimit * 0.85
            placed[i].x += (dx / d) * pull
            placed[i].z += (dz / d) * pull
        }
    }

    // --- visibility-bias micro-pass --------------------------------------
    // Every cube already shows its logo on whichever real face is most
    // camera-facing (computed against the live camera at render time in
    // buildCube) - this pass only asks whether enough of those chosen faces
    // are readable rather than grazing. It approximates the camera with the
    // fixed art-directed azimuth and a representative default elevation
    // (the live camera can still be adjusted by the Camera Elevation/
    // Distance controls; this is a coarse, deterministic nudge, not a
    // pixel-exact prediction). If fewer than 5 of 12+ cubes clear a modest
    // "facing" threshold, the least composition-critical grounded/leaning/
    // edge cubes (never heroes, already the most readable) get a small,
    // deterministic yaw nudge toward a better-facing orientation - position,
    // tilt, contact, and stacking are all left untouched.
    {
        const approxElevRad = (22 * Math.PI) / 180
        const approxCameraDir = new THREE.Vector3(
            Math.sin(CAMERA_AZIMUTH) * Math.cos(approxElevRad),
            Math.sin(approxElevRad),
            Math.cos(CAMERA_AZIMUTH) * Math.cos(approxElevRad)
        ).normalize()
        const faceAxes = [
            new THREE.Vector3(1, 0, 0),
            new THREE.Vector3(-1, 0, 0),
            new THREE.Vector3(0, 1, 0),
            new THREE.Vector3(0, 0, 1),
            new THREE.Vector3(0, 0, -1),
        ]
        const bestFaceDot = (tiltX: number, yaw: number, tiltZ: number) => {
            const invQ = buildRestQuaternion(tiltX, yaw, tiltZ).invert()
            const localDir = approxCameraDir.clone().applyQuaternion(invQ)
            let best = -Infinity
            for (const axis of faceAxes) best = Math.max(best, axis.dot(localDir))
            return best
        }

        // A well-oriented face can still be hidden behind a nearer cube -
        // orientation alone isn't "visible". Approximate occlusion with a
        // cheap orthographic-style check: another cube counts as blocking
        // when it sits closer to the camera along the view direction and
        // lands within roughly a cube-width of the same line of sight.
        const isOccluded = (index: number) => {
            const target = placed[index]
            const targetDepth =
                target.x * approxCameraDir.x + target.y * approxCameraDir.y + target.z * approxCameraDir.z
            for (let j = 0; j < placed.length; j++) {
                if (j === index) continue
                const o = placed[j]
                const oDepth = o.x * approxCameraDir.x + o.y * approxCameraDir.y + o.z * approxCameraDir.z
                if (oDepth <= targetDepth) continue
                const dx = o.x - target.x
                const dy = o.y - target.y
                const dz = o.z - target.z
                const along = dx * approxCameraDir.x + dy * approxCameraDir.y + dz * approxCameraDir.z
                const latX = dx - along * approxCameraDir.x
                const latY = dy - along * approxCameraDir.y
                const latZ = dz - along * approxCameraDir.z
                const lateralDist = Math.sqrt(latX * latX + latY * latY + latZ * latZ)
                if (lateralDist < CUBE_SIZE * 0.52) return true
            }
            return false
        }

        const VISIBLE_THRESHOLD = 0.72
        // Internal target kept one above the requested minimum of 5 - this
        // proxy metric (orientation + a coarse orthographic occlusion
        // approximation) is necessarily imprecise next to the real
        // perspective render, so aiming one higher is the margin that keeps
        // the delivered count reliably at or above 5, not exactly on the line.
        const MIN_VISIBLE = 6
        const isVisible = (index: number) =>
            bestFaceDot(placed[index].tiltX, placed[index].yaw, placed[index].tiltZ) > VISIBLE_THRESHOLD &&
            !isOccluded(index)

        let visibleCount = 0
        for (let i = 0; i < placed.length; i++) if (isVisible(i)) visibleCount++

        if (visibleCount < MIN_VISIBLE) {
            // Candidates: not occluded (a yaw nudge can't fix being physically
            // blocked), not a hero (already the most readable), worst-facing
            // first so the fix targets cubes that actually need it.
            const adjustable = placed
                .map((p, idx) => ({
                    idx,
                    dot: bestFaceDot(p.tiltX, p.yaw, p.tiltZ),
                    occluded: isOccluded(idx),
                }))
                .filter((entry) => placed[entry.idx].role !== "hero" && !entry.occluded)
                .sort((a, b) => a.dot - b.dot)

            for (const { idx } of adjustable) {
                if (visibleCount >= MIN_VISIBLE) break
                if (isVisible(idx)) continue
                const p = placed[idx]
                for (const deltaDeg of [25, -25, 50, -50, 75, -75]) {
                    const testYaw = p.yaw + (deltaDeg * Math.PI) / 180
                    if (bestFaceDot(p.tiltX, testYaw, p.tiltZ) > VISIBLE_THRESHOLD) {
                        p.yaw = testYaw
                        if (isVisible(idx)) visibleCount++
                        break
                    }
                }
            }
        }
    }

    return placed
}

// ---------------------------------------------------------------------------
// Procedural monogram fallback (no bundled third-party logos)
// ---------------------------------------------------------------------------

const INK = "#2A2620"

function drawMonogram(name: string): HTMLCanvasElement {
    const canvas = document.createElement("canvas")
    canvas.width = 256
    canvas.height = 256
    const ctx = canvas.getContext("2d")
    if (ctx) {
        ctx.clearRect(0, 0, 256, 256)
        const parts = name.trim().split(/\s+/).filter(Boolean)
        const letters = parts.length > 1 ? parts[0][0] + parts[1][0] : name.slice(0, 2)
        ctx.fillStyle = INK
        ctx.font = "700 92px -apple-system, 'Segoe UI', sans-serif"
        ctx.textAlign = "center"
        ctx.textBaseline = "middle"
        ctx.fillText(letters.toUpperCase(), 128, 134)
    }
    return canvas
}

// ---------------------------------------------------------------------------
// Default demo marks - original, generic vector-style symbols in the visual
// character of a modern SaaS/design-tool wordmark set (ring, grid, wave,
// chevron, cross, dots, arc, diamond, hexagon, monogram, overlapping
// circles, triangle). None of these represent any real company or brand.
// ---------------------------------------------------------------------------

function drawDemoMark(kind: MarkKind, name: string, color: string): HTMLCanvasElement {
    const canvas = document.createElement("canvas")
    const size = 256
    canvas.width = size
    canvas.height = size
    const ctx = canvas.getContext("2d")
    if (!ctx) return canvas
    ctx.clearRect(0, 0, size, size)
    ctx.fillStyle = color
    ctx.strokeStyle = color
    ctx.lineCap = "round"
    ctx.lineJoin = "round"
    const c = size / 2

    switch (kind) {
        case "ring": {
            // Two interlocking rings rather than one plain donut - reads as
            // a partnership/connectivity mark, not a generic icon glyph.
            ctx.lineWidth = 16
            ctx.globalAlpha = 0.92
            ctx.beginPath()
            ctx.arc(c - 24, c, 46, 0, Math.PI * 2)
            ctx.stroke()
            ctx.beginPath()
            ctx.arc(c + 24, c, 46, 0, Math.PI * 2)
            ctx.stroke()
            ctx.globalAlpha = 1
            break
        }
        case "grid": {
            // Asymmetric block system rather than a uniform 2x2 - reads as
            // a considered layout mark, not a plain grid icon.
            const blocks: [number, number, number, number][] = [
                [-64, -56, 40, 40],
                [12, -56, 52, 26],
                [-64, -6, 26, 62],
                [-24, 18, 88, 38],
            ]
            for (const [dx, dy, w, h] of blocks) ctx.fillRect(c + dx, c + dy, w, h)
            break
        }
        case "wave": {
            ctx.lineWidth = 20
            ctx.beginPath()
            ctx.moveTo(c - 78, c + 14)
            ctx.bezierCurveTo(c - 40, c - 46, c - 6, c - 46, c + 6, c + 8)
            ctx.bezierCurveTo(c + 18, c + 46, c + 46, c + 46, c + 78, c - 14)
            ctx.stroke()
            break
        }
        case "chevron": {
            ctx.lineWidth = 22
            ctx.beginPath()
            ctx.moveTo(c - 56, c + 30)
            ctx.lineTo(c, c - 34)
            ctx.lineTo(c + 56, c + 30)
            ctx.stroke()
            break
        }
        case "cross": {
            // A slightly rotated, unequal-arm cross - a bolt/spark mark
            // rather than a plain plus-sign glyph.
            ctx.save()
            ctx.translate(c, c)
            ctx.rotate((14 * Math.PI) / 180)
            const w = 22
            ctx.fillRect(-w / 2, -80, w, 130)
            ctx.fillRect(-64, -w / 2, 118, w)
            ctx.restore()
            break
        }
        case "dots": {
            const r = 20
            const pts: [number, number][] = [
                [c, c - 46],
                [c - 46, c + 34],
                [c + 46, c + 34],
            ]
            for (const [x, y] of pts) {
                ctx.beginPath()
                ctx.arc(x, y, r, 0, Math.PI * 2)
                ctx.fill()
            }
            break
        }
        case "arc": {
            ctx.lineWidth = 24
            ctx.beginPath()
            ctx.arc(c, c + 18, 66, Math.PI * 1.15, Math.PI * 1.92)
            ctx.stroke()
            break
        }
        case "diamond": {
            ctx.lineWidth = 18
            ctx.beginPath()
            ctx.moveTo(c, c - 66)
            ctx.lineTo(c + 66, c)
            ctx.lineTo(c, c + 66)
            ctx.lineTo(c - 66, c)
            ctx.closePath()
            ctx.stroke()
            break
        }
        case "hex": {
            ctx.lineWidth = 18
            ctx.beginPath()
            for (let i = 0; i < 6; i++) {
                const a = (Math.PI / 3) * i - Math.PI / 2
                const x = c + Math.cos(a) * 62
                const y = c + Math.sin(a) * 62
                if (i === 0) ctx.moveTo(x, y)
                else ctx.lineTo(x, y)
            }
            ctx.closePath()
            ctx.stroke()
            break
        }
        case "circles": {
            // A solid disc with a crescent cut from an offset circle - an
            // eclipse mark, distinct from the stroked interlocking rings.
            ctx.beginPath()
            ctx.arc(c, c, 64, 0, Math.PI * 2)
            ctx.fill()
            ctx.globalCompositeOperation = "destination-out"
            ctx.beginPath()
            ctx.arc(c + 30, c - 12, 54, 0, Math.PI * 2)
            ctx.fill()
            ctx.globalCompositeOperation = "source-over"
            break
        }
        case "triangle": {
            ctx.beginPath()
            ctx.moveTo(c, c - 62)
            ctx.lineTo(c + 58, c + 46)
            ctx.lineTo(c - 58, c + 46)
            ctx.closePath()
            ctx.fill()
            break
        }
        case "bars": {
            const w = 26
            const gap = 14
            const heights = [56, 92, 72]
            const totalW = w * 3 + gap * 2
            let x = c - totalW / 2
            for (const h of heights) {
                ctx.fillRect(x, c - h / 2, w, h)
                x += w + gap
            }
            break
        }
        case "wordmark": {
            const letters = (name.trim().slice(0, 8) || "Mark").toUpperCase()
            ctx.font = "700 52px -apple-system, 'Segoe UI', sans-serif"
            ctx.textAlign = "center"
            ctx.textBaseline = "middle"
            ctx.save()
            const metrics = ctx.measureText(letters)
            const maxW = 190
            if (metrics.width > maxW) {
                const scale = maxW / metrics.width
                ctx.translate(c, c + 4)
                ctx.scale(scale, 1)
                ctx.fillText(letters, 0, 0)
            } else {
                ctx.fillText(letters, c, c + 4)
            }
            ctx.restore()
            break
        }
        case "mono":
        default: {
            // A bold letterform with a corner notched out - a crafted
            // logotype cut, not a raw typed character.
            const letter = (name.trim()[0] || "?").toUpperCase()
            ctx.font = "700 132px -apple-system, 'Segoe UI', sans-serif"
            ctx.textAlign = "center"
            ctx.textBaseline = "middle"
            ctx.fillText(letter, c, c + 6)
            ctx.globalCompositeOperation = "destination-out"
            ctx.beginPath()
            ctx.moveTo(c + 34, c - 74)
            ctx.lineTo(c + 74, c - 74)
            ctx.lineTo(c + 74, c - 34)
            ctx.closePath()
            ctx.fill()
            ctx.globalCompositeOperation = "source-over"
            break
        }
    }

    return canvas
}

function drawGroundGradient(): HTMLCanvasElement {
    const canvas = document.createElement("canvas")
    canvas.width = 512
    canvas.height = 512
    const ctx = canvas.getContext("2d")
    if (ctx) {
        const grad = ctx.createRadialGradient(256, 256, 20, 256, 256, 256)
        grad.addColorStop(0, "rgba(30,26,18,0.22)")
        grad.addColorStop(0.55, "rgba(30,26,18,0.08)")
        grad.addColorStop(1, "rgba(30,26,18,0)")
        ctx.fillStyle = grad
        ctx.fillRect(0, 0, 512, 512)
    }
    return canvas
}

// Tighter, darker falloff than the wide cluster gradient above - used per
// cube for a short, dark "weight" shadow immediately at its floor contact
// point, distinct from the soft wide shadow that reads as scene lighting
// direction.
function drawContactGradient(): HTMLCanvasElement {
    const canvas = document.createElement("canvas")
    canvas.width = 256
    canvas.height = 256
    const ctx = canvas.getContext("2d")
    if (ctx) {
        const grad = ctx.createRadialGradient(128, 128, 4, 128, 128, 128)
        grad.addColorStop(0, "rgba(24,20,14,0.42)")
        grad.addColorStop(0.5, "rgba(24,20,14,0.16)")
        grad.addColorStop(1, "rgba(24,20,14,0)")
        ctx.fillStyle = grad
        ctx.fillRect(0, 0, 256, 256)
    }
    return canvas
}

// Curated, modern-minimal palette - saturated but tasteful, spread around
// the color wheel, deliberately not matching any real company's signature
// color so these read as original iconography rather than a real brand.
const DEMO_MARKS: { name: string; kind: MarkKind; color: string }[] = [
    { name: "Meridian", kind: "arc", color: "#2563EB" }, // organic curve, electric blue
    { name: "Nodal", kind: "ring", color: "#7C3AED" }, // interlocking rings, violet
    { name: "Fathom", kind: "grid", color: "#0891B2" }, // system/grid mark, cyan
    { name: "Lumen", kind: "wordmark", color: "#1E293B" }, // small wordmark, near-black
    { name: "Anvil", kind: "chevron", color: "#E11D48" }, // angular symbol, coral/red
    { name: "Orbital", kind: "dots", color: "#EA580C" }, // geometric symbol, orange
    { name: "Solari", kind: "wave", color: "#65A30D" }, // organic curve, lime/green
    { name: "Kernel", kind: "mono", color: "#18181B" }, // abstract letterform, near-black
    { name: "Halcyon", kind: "hex", color: "#7C3AED" }, // geometric symbol, violet
    { name: "Cobalt", kind: "diamond", color: "#3B82F6" }, // angular symbol, electric blue
    { name: "Rivet", kind: "bars", color: "#F97316" }, // system mark, orange
    { name: "Thresh", kind: "circles", color: "#F43F5E" }, // eclipse mark, coral/red
]

// Non-uniform per-mark sizing so wide marks and simple symbols don't all
// share the exact same footprint on the cube face.
const MARK_ASPECT: Record<MarkKind, [number, number]> = {
    ring: [1.1, 1.1],
    grid: [1.05, 1.05],
    wave: [1.2, 0.82],
    chevron: [1.05, 1.0],
    cross: [1.0, 1.0],
    dots: [1.0, 1.0],
    arc: [1.12, 0.92],
    diamond: [1.0, 1.0],
    hex: [1.08, 1.08],
    mono: [0.85, 0.95],
    circles: [1.05, 1.05],
    triangle: [1.0, 1.0],
    bars: [1.25, 0.82],
    wordmark: [1.55, 0.5],
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

const visuallyHidden: CSSProperties = {
    position: "absolute",
    width: 1,
    height: 1,
    padding: 0,
    margin: -1,
    overflow: "hidden",
    clip: "rect(0,0,0,0)",
    whiteSpace: "nowrap",
    border: 0,
}

/**
 * 3D Logo Cubes
 *
 * A procedurally arranged, WebGL-rendered pile of rounded logo cubes.
 *
 * @framerIntrinsicWidth 640
 * @framerIntrinsicHeight 520
 *
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight any-prefer-fixed
 */
export default function LogoCubes(props: LogoCubesProps) {
    const {
        logos = [],
        cubeColor = "#F5F2E9",
        cornerRadius = 0.14,
        roughness = 0.36,
        clearcoat = 0.38,
        logoScaleDefault = 1,
        spread = 0.55,
        depth = 0.55,
        density = 0.5,
        randomness = 0.5,
        seed = 7,
        hover = true,
        hoverLift = 0.1,
        hoverTilt = 3,
        hoverScale = 1.02,
        pointerParallax = false,
        showFloor = true,
        floorColor = "#F1EFE7",
        transparentBackground = false,
        backgroundColor = "#FAFAF8",
        cameraDistance = 1,
        cameraElevation = 22,
        lightingIntensity = 1,
        shadowStrength = 0.6,
        quality = "auto",
        mobileScale = 0.9,
        mobileQuality = "auto",
        style,
    } = props

    const mountRef = useRef<HTMLDivElement>(null)
    const [webglSupported, setWebglSupported] = useState(true)
    const isStatic = useIsStaticRenderer()

    const resolvedLogos: LogoItem[] = useMemo(() => {
        if (logos && logos.length > 0) return logos
        return DEMO_MARKS.map((m) => ({ name: m.name, logoScale: 1, markKind: m.kind, markColor: m.color }))
    }, [logos])

    // -----------------------------------------------------------------
    // WebGL capability probe (once)
    // -----------------------------------------------------------------
    useEffect(() => {
        if (typeof window === "undefined") return
        try {
            const test = document.createElement("canvas")
            const gl = test.getContext("webgl2") || test.getContext("webgl")
            if (!gl) setWebglSupported(false)
        } catch {
            setWebglSupported(false)
        }
    }, [])

    // -----------------------------------------------------------------
    // Scene lifecycle
    // -----------------------------------------------------------------
    useEffect(() => {
        if (!webglSupported || isStatic === undefined) return
        const mount = mountRef.current
        if (!mount) return

        let disposed = false
        const prefersReducedMotion =
            typeof window !== "undefined" &&
            window.matchMedia &&
            window.matchMedia("(prefers-reduced-motion: reduce)").matches

        const isThumbnail = RenderTarget.current() === RenderTarget.thumbnail

        // --- quality resolution ---------------------------------------
        const mobileBreakpoint = 520
        let containerW = mount.clientWidth || 640
        let containerH = mount.clientHeight || 520
        const isMobile = containerW < mobileBreakpoint

        function resolveQuality(mode: QualityMode): "high" | "performance" {
            if (mode === "high") return "high"
            if (mode === "performance") return "performance"
            const cores =
                typeof navigator !== "undefined" && (navigator as any).hardwareConcurrency
                    ? (navigator as any).hardwareConcurrency
                    : 4
            if (cores < 4 || containerW < 420) return "performance"
            return "high"
        }
        const activeQualityMode = isMobile ? mobileQuality : quality
        const resolvedQuality = resolveQuality(activeQualityMode)
        const dprCap = isThumbnail ? 1 : resolvedQuality === "high" ? 2 : 1.35
        const shadowsEnabled = !isThumbnail && resolvedQuality === "high"
        const shadowMapSize = resolvedQuality === "high" ? 1024 : 512

        // --- renderer ----------------------------------------------------
        const renderer = new THREE.WebGLRenderer({
            antialias: resolvedQuality === "high",
            alpha: transparentBackground,
            powerPreference: "high-performance",
        })
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, dprCap))
        renderer.setSize(containerW, containerH)
        renderer.outputColorSpace = THREE.SRGBColorSpace
        // Filmic tone mapping + a trimmed exposure keeps white top faces from
        // clipping to flat 255 under the bright environment - without it the
        // geometry loses its tonal separation and reads as overexposed.
        renderer.toneMapping = THREE.ACESFilmicToneMapping
        renderer.toneMappingExposure = 0.92
        renderer.shadowMap.enabled = shadowsEnabled
        renderer.shadowMap.type = THREE.PCFSoftShadowMap
        if (!transparentBackground) renderer.setClearColor(backgroundColor, 1)
        else renderer.setClearColor(0x000000, 0)
        renderer.domElement.style.position = "absolute"
        renderer.domElement.style.inset = "0"
        renderer.domElement.style.width = "100%"
        renderer.domElement.style.height = "100%"
        renderer.domElement.style.display = "block"
        mount.appendChild(renderer.domElement)

        const scene = new THREE.Scene()
        if (!transparentBackground) scene.background = new THREE.Color(backgroundColor)

        const camera = new THREE.PerspectiveCamera(38, containerW / containerH, 0.1, 100)

        // --- environment ---------------------------------------------------
        let envRT: any = null
        if (!isThumbnail) {
            const pmrem = new THREE.PMREMGenerator(renderer)
            envRT = pmrem.fromScene(new RoomEnvironment(), 0.04)
            scene.environment = envRT.texture
            if ("environmentIntensity" in scene) (scene as any).environmentIntensity = 0.55
            pmrem.dispose()
        }

        // --- lights ---------------------------------------------------
        // Large-soft-source studio feeling: a key from upper-left/front, a
        // dim fill from the opposite side, plus ambient environment - kept
        // deliberately modest so the environment map doesn't flatten every
        // gradient the key light is there to create.
        const key = new THREE.DirectionalLight(0xfff3e6, 1.55 * lightingIntensity)
        // Steep overhead angle (upper-left/front, but high) so cast shadows
        // fall short and close to each object instead of stretching out to
        // the side - weight, not a long obvious shadow.
        key.position.set(-1.75, 4.6, 1.85)
        key.castShadow = shadowsEnabled
        if (shadowsEnabled) {
            key.shadow.mapSize.set(shadowMapSize, shadowMapSize)
            key.shadow.camera.near = 1
            key.shadow.camera.far = 12
            // Tightened to the pile's actual (now denser) footprint - a
            // frustum much larger than the content under-samples the shadow
            // map and makes cast shadows look blocky/hard-edged instead of
            // soft, even with a large PCF blur radius.
            key.shadow.camera.left = -2.1
            key.shadow.camera.right = 2.1
            key.shadow.camera.top = 2.1
            key.shadow.camera.bottom = -2.1
            key.shadow.radius = 10
            key.shadow.bias = -0.003
        }
        scene.add(key)
        const fillLight = new THREE.DirectionalLight(0xeaf0f6, 0.4 * lightingIntensity)
        fillLight.position.set(2.8, 2.2, -1.6)
        scene.add(fillLight)
        const hemi = new THREE.HemisphereLight(0xfaf6ec, 0x3a352b, 0.32 * lightingIntensity)
        scene.add(hemi)

        // --- shared geometry & materials -------------------------------
        const cornerR = Math.min(0.46, Math.max(0, cornerRadius)) * (CUBE_SIZE / 2)
        const cubeGeo = new RoundedBoxGeometry(CUBE_SIZE, CUBE_SIZE, CUBE_SIZE, 4, cornerR)
        const planeGeo = new THREE.PlaneGeometry(1, 1)

        const materialCache = new Map<string, any>()
        function getMaterial(color: string) {
            const key = color
            let mat = materialCache.get(key)
            if (!mat) {
                mat = new THREE.MeshPhysicalMaterial({
                    color,
                    roughness: Math.min(1, Math.max(0, roughness)),
                    metalness: 0,
                    clearcoat: Math.min(1, Math.max(0, clearcoat)),
                    clearcoatRoughness: 0.2,
                    envMapIntensity: 0.7,
                })
                materialCache.set(key, mat)
            }
            return mat
        }

        // --- floor -------------------------------------------------------
        let floorMesh: any = null
        let groundMesh: any = null
        if (showFloor) {
            const floorGeo = new THREE.PlaneGeometry(40, 40)
            const floorMat = new THREE.MeshStandardMaterial({
                color: floorColor,
                roughness: 0.88,
                metalness: 0,
            })
            floorMesh = new THREE.Mesh(floorGeo, floorMat)
            floorMesh.rotation.x = -Math.PI / 2
            floorMesh.receiveShadow = shadowsEnabled
            scene.add(floorMesh)

            // Wide, soft - reads as overall lighting direction, not weight.
            const groundTex = new THREE.CanvasTexture(drawGroundGradient())
            groundTex.colorSpace = THREE.SRGBColorSpace
            const groundGeo = new THREE.PlaneGeometry(6.4, 5.6)
            const groundMat = new THREE.MeshBasicMaterial({
                map: groundTex,
                transparent: true,
                opacity: 0.5 * shadowStrength,
                depthWrite: false,
            })
            groundMesh = new THREE.Mesh(groundGeo, groundMat)
            groundMesh.rotation.x = -Math.PI / 2
            groundMesh.position.y = 0.0015
            scene.add(groundMesh)
        }

        // Short, dark, tight - one per floor-resting cube, reads as weight
        // at the actual contact point rather than scene-wide lighting.
        const contactShadowGeo = new THREE.PlaneGeometry(1, 1)
        const contactShadowTex = new THREE.CanvasTexture(drawContactGradient())
        contactShadowTex.colorSpace = THREE.SRGBColorSpace
        const contactShadowMat = new THREE.MeshBasicMaterial({
            map: contactShadowTex,
            transparent: true,
            opacity: 0.64 * shadowStrength,
            depthWrite: false,
        })
        const contactShadowMeshes: any[] = []

        // --- arrangement ---------------------------------------------------
        const activeMobileScale = isMobile ? Math.min(1, Math.max(0.5, mobileScale)) : 1
        const items = resolvedLogos.slice(0, 24)
        // On narrow/portrait frames, reshape the composition envelope itself
        // (narrower, deeper) rather than only zooming the camera out - the
        // same seed still produces a deterministic, comparably substantial
        // cluster instead of the same wide cluster shrunk down to look tiny.
        const effSpread = isMobile ? spread * 0.72 : spread
        const effDepth = isMobile ? Math.min(1, depth * 1.15) : depth
        const arrangement = generateArrangement(
            items.length,
            seed,
            effSpread,
            effDepth,
            density,
            randomness
        )

        let maxHorizontal = 0.6
        let maxHeight = CUBE_SIZE
        let centroidX = 0
        for (const p of arrangement) {
            maxHorizontal = Math.max(maxHorizontal, Math.sqrt(p.x * p.x + p.z * p.z) + FOOTPRINT_R)
            maxHeight = Math.max(maxHeight, p.y + p.topY)
            centroidX += p.x
        }
        centroidX = arrangement.length > 0 ? centroidX / arrangement.length : 0
        const boundingRadius = Math.max(maxHorizontal * 1.02, maxHeight * 1.08)

        const pileGroup = new THREE.Group()
        pileGroup.scale.setScalar(activeMobileScale)
        scene.add(pileGroup)

        const textureLoader = new THREE.TextureLoader()
        textureLoader.crossOrigin = "anonymous"
        const textureCache = new Map<string, any>()

        function rasterizeToTexture(source: HTMLCanvasElement | HTMLImageElement, key: string) {
            const cached = textureCache.get(key)
            if (cached) return cached
            const canvas = document.createElement("canvas")
            const maxDim = 512
            let w = (source as any).width || maxDim
            let h = (source as any).height || maxDim
            const scale = Math.min(1, maxDim / Math.max(w, h))
            canvas.width = Math.max(1, Math.round(w * scale))
            canvas.height = Math.max(1, Math.round(h * scale))
            const ctx = canvas.getContext("2d")
            if (ctx) {
                try {
                    ctx.drawImage(source as any, 0, 0, canvas.width, canvas.height)
                } catch {
                    // cross-origin draw failure - leave transparent
                }
            }
            const tex = new THREE.CanvasTexture(canvas)
            tex.colorSpace = THREE.SRGBColorSpace
            tex.anisotropy = renderer.capabilities.getMaxAnisotropy()
            tex.needsUpdate = true
            textureCache.set(key, tex)
            return tex
        }

        const cubeGroups: any[] = []
        const cubeMeshes: any[] = []
        const cameraDirWorld = new THREE.Vector3()

        const azimuth = CAMERA_AZIMUTH
        const elevRad = THREE.MathUtils.degToRad(Math.min(55, Math.max(10, cameraElevation)))
        const vFovRad = THREE.MathUtils.degToRad(38)
        // A photographed composition isn't mechanically centered on the
        // bounding box - offset the look target slightly using the pile's
        // own (seeded, deterministic) centroid rather than forcing 0.
        const lookTarget = new THREE.Vector3(centroidX * 0.4, maxHeight * 0.34, 0)

        // Fit against whichever axis is more constraining - a narrow/portrait
        // frame has a much tighter horizontal FOV than vertical, and fitting
        // only to the vertical FOV (as if aspect were always landscape) crops
        // the pile's sides on tall/narrow frames. Re-run on every resize so
        // a live aspect-ratio change (not just a remount) keeps the fit correct.
        function fitCameraToContainer(w: number, h: number) {
            const aspect = w / h
            const hFovRad = 2 * Math.atan(Math.tan(vFovRad / 2) * aspect)
            const distForVertical = boundingRadius / Math.tan(vFovRad / 2)
            const distForHorizontal = boundingRadius / Math.tan(hFovRad / 2)
            const fitDistance = Math.max(distForVertical, distForHorizontal) * 0.86
            const dist = fitDistance * Math.min(2.2, Math.max(0.4, cameraDistance))
            camera.position.set(
                Math.sin(azimuth) * Math.cos(elevRad) * dist,
                Math.sin(elevRad) * dist + CUBE_SIZE * 0.3,
                Math.cos(azimuth) * Math.cos(elevRad) * dist
            )
            camera.lookAt(lookTarget)
            camera.updateMatrixWorld()
            if (!transparentBackground) {
                scene.fog = new THREE.Fog(new THREE.Color(backgroundColor).getHex(), dist * 0.85, dist * 2.1)
            }
            return dist
        }
        fitCameraToContainer(containerW, containerH)

        function buildCube(item: LogoItem, placement: PlacedCube, index: number) {
            const group = new THREE.Group()
            group.position.set(placement.x, placement.y, placement.z)
            const restQuat = new THREE.Quaternion().setFromEuler(
                new THREE.Euler(placement.tiltX, placement.yaw, placement.tiltZ)
            )
            group.quaternion.copy(restQuat)
            group.userData.rest = {
                position: group.position.clone(),
                quaternion: restQuat.clone(),
            }
            group.userData.index = index
            group.userData.hasLink = Boolean(item.link)

            const mat = item.colorOverride ? getMaterial(item.colorOverride) : getMaterial(cubeColor)
            const cubeMesh = new THREE.Mesh(cubeGeo, mat)
            cubeMesh.castShadow = shadowsEnabled
            cubeMesh.receiveShadow = shadowsEnabled
            cubeMesh.userData.cubeIndex = index
            group.add(cubeMesh)
            cubeMeshes.push(cubeMesh)

            // choose the local face most facing the camera (excluding down)
            cameraDirWorld.copy(camera.position).sub(group.position).normalize()
            const invQuat = restQuat.clone().invert()
            const localDir = cameraDirWorld.clone().applyQuaternion(invQuat)
            const candidates: [any, string][] = [
                [new THREE.Vector3(1, 0, 0), "x+"],
                [new THREE.Vector3(-1, 0, 0), "x-"],
                [new THREE.Vector3(0, 1, 0), "y+"],
                [new THREE.Vector3(0, 0, 1), "z+"],
                [new THREE.Vector3(0, 0, -1), "z-"],
            ]
            let bestAxis = candidates[0][0]
            let bestDot = -Infinity
            for (const [axis] of candidates) {
                const d = axis.dot(localDir)
                if (d > bestDot) {
                    bestDot = d
                    bestAxis = axis
                }
            }

            const key = item.image?.src ? "img:" + item.image.src : "mono:" + item.name
            let texture: any
            if (item.image?.src) {
                const cached = textureCache.get(key)
                if (cached) {
                    texture = cached
                } else {
                    texture = new THREE.Texture()
                    textureCache.set(key, texture)
                    const img = new Image()
                    img.crossOrigin = "anonymous"
                    img.onload = () => {
                        if (disposed) return
                        const t = rasterizeToTexture(img, key)
                        texture.image = t.image
                        texture.needsUpdate = true
                    }
                    img.onerror = () => {
                        if (disposed) return
                        const t = rasterizeToTexture(drawMonogram(item.name || "?"), key + ":fallback")
                        texture.image = t.image
                        texture.needsUpdate = true
                    }
                    img.src = item.image.src
                }
            } else if (item.markKind) {
                texture = rasterizeToTexture(
                    drawDemoMark(item.markKind, item.name || "?", item.markColor || INK),
                    key
                )
            } else {
                texture = rasterizeToTexture(drawMonogram(item.name || "?"), key)
            }

            const logoMat = new THREE.MeshBasicMaterial({
                map: texture,
                transparent: true,
                alphaTest: 0.12,
                toneMapped: false,
                depthWrite: false,
            })
            const logoPlane = new THREE.Mesh(planeGeo, logoMat)
            // Flush with the face rather than visibly hovering above it - a
            // printed/inset mark, not a floating label.
            const faceOffset = CUBE_SIZE / 2 + 0.0016
            logoPlane.position.copy(bestAxis).multiplyScalar(faceOffset)
            // Orient explicitly from world-up rather than THREE's shortest-arc
            // setFromUnitVectors, which leaves the roll around the face normal
            // undefined and can render text upside-down or mirrored.
            {
                const worldNormal = bestAxis.clone().applyQuaternion(restQuat).normalize()
                const refUp =
                    Math.abs(worldNormal.y) > 0.92 ? new THREE.Vector3(0, 0, -1) : new THREE.Vector3(0, 1, 0)
                const xAxis = new THREE.Vector3().crossVectors(refUp, worldNormal).normalize()
                const yAxis = new THREE.Vector3().crossVectors(worldNormal, xAxis).normalize()
                const worldPlaneQuat = new THREE.Quaternion().setFromRotationMatrix(
                    new THREE.Matrix4().makeBasis(xAxis, yAxis, worldNormal)
                )
                logoPlane.quaternion.copy(restQuat).invert().multiply(worldPlaneQuat)
            }
            // The object is the hero, the mark is an identity detail - keep
            // the default occupancy modest rather than dominating the face.
            // Geometry-aware sizing: wide wordmarks run wider/shorter,
            // simple symbols read slightly larger, detailed marks stay
            // moderate - not every mark forced into the same footprint.
            const s = 0.52 * (item.logoScale ?? 1) * logoScaleDefault
            const [mx, my] = item.markKind ? MARK_ASPECT[item.markKind] : [1, 1]
            logoPlane.scale.set(s * mx, s * my, 1)
            group.add(logoPlane)

            pileGroup.add(group)
            cubeGroups.push(group)
        }

        items.forEach((item, i) => buildCube(item, arrangement[i], i))

        if (showFloor) {
            for (let i = 0; i < arrangement.length; i++) {
                const p = arrangement[i]
                if (p.supportDepth > 0) continue
                const shadow = new THREE.Mesh(contactShadowGeo, contactShadowMat)
                shadow.rotation.x = -Math.PI / 2
                shadow.position.set(p.x, 0.001, p.z)
                const sc = CUBE_SIZE * 1.3
                shadow.scale.set(sc, sc, 1)
                pileGroup.add(shadow)
                contactShadowMeshes.push(shadow)
            }
        }

        // Very subtle mirrored reflection of the cube bodies only (no logo
        // planes - a mirrored logo reads as an obvious fake). Skipped on
        // constrained quality tiers and for the thumbnail render target,
        // since it doubles the cube draw calls for a restrained effect that
        // the brief explicitly said was optional if it added real cost.
        let reflectionGroup: any = null
        let reflectionMat: any = null
        if (showFloor && resolvedQuality === "high" && !isThumbnail) {
            reflectionGroup = new THREE.Group()
            reflectionGroup.scale.set(1, -1, 1)
            reflectionMat = new THREE.MeshBasicMaterial({
                color: cubeColor,
                transparent: true,
                opacity: 0.03,
                depthWrite: false,
                side: THREE.DoubleSide,
                fog: true,
            })
            for (const group of cubeGroups) {
                const mesh = new THREE.Mesh(cubeGeo, reflectionMat)
                mesh.position.copy(group.position)
                mesh.quaternion.copy(group.quaternion)
                reflectionGroup.add(mesh)
            }
            pileGroup.add(reflectionGroup)
        }

        // -----------------------------------------------------------------
        // Render-on-demand loop
        // -----------------------------------------------------------------
        let needsRender = true
        let rafId: number | null = null
        let rafActive = false

        function requestRender() {
            needsRender = true
            if (!rafActive) startLoop()
        }

        // -----------------------------------------------------------------
        // Hover spring state (per cube)
        // -----------------------------------------------------------------
        interface SpringState {
            lift: number
            liftV: number
            fwd: number
            fwdV: number
            tilt: number
            tiltV: number
            scale: number
            scaleV: number
            target: number
        }
        const springs: SpringState[] = cubeGroups.map(() => ({
            lift: 0,
            liftV: 0,
            fwd: 0,
            fwdV: 0,
            tilt: 0,
            tiltV: 0,
            scale: 0,
            scaleV: 0,
            target: 0,
        }))
        let hoveredIndex = -1
        const forwardDirs: any[] = cubeGroups.map((g) =>
            camera.position.clone().sub(g.position).normalize()
        )

        function setHovered(index: number) {
            if (hoveredIndex === index) return
            hoveredIndex = index
            for (let i = 0; i < springs.length; i++) springs[i].target = i === index ? 1 : 0
            if (prefersReducedMotion) {
                for (let i = 0; i < springs.length; i++) {
                    const s = springs[i]
                    s.lift = s.target * hoverLift
                    s.fwd = s.target * (hoverLift * 0.4)
                    s.tilt = s.target * THREE.MathUtils.degToRad(hoverTilt)
                    s.scale = s.target * (hoverScale - 1)
                }
                applySprings()
                requestRender()
            } else {
                requestRender()
            }
        }

        function applySprings() {
            for (let i = 0; i < cubeGroups.length; i++) {
                const g = cubeGroups[i]
                const s = springs[i]
                const rest = g.userData.rest
                g.position.copy(rest.position)
                g.position.y += s.lift
                g.position.addScaledVector(forwardDirs[i], s.fwd)
                g.quaternion.copy(rest.quaternion)
                g.rotateX(s.tilt * 0.6)
                g.rotateZ(s.tilt * 0.4)
                const sc = 1 + s.scale
                g.scale.set(sc, sc, sc)
            }
        }

        let lastTime = performance.now()
        function stepSprings(dt: number) {
            let anyActive = false
            const stiffness = 170
            const damping = 18
            for (const s of springs) {
                const targetLift = s.target * hoverLift
                const targetFwd = s.target * (hoverLift * 0.4)
                const targetTilt = s.target * THREE.MathUtils.degToRad(hoverTilt)
                const targetScale = s.target * (hoverScale - 1)

                const step = (value: number, vel: number, target: number) => {
                    const force = (target - value) * stiffness - vel * damping
                    const nv = vel + force * dt
                    const nx = value + nv * dt
                    return [nx, nv] as const
                }

                ;[s.lift, s.liftV] = step(s.lift, s.liftV, targetLift)
                ;[s.fwd, s.fwdV] = step(s.fwd, s.fwdV, targetFwd)
                ;[s.tilt, s.tiltV] = step(s.tilt, s.tiltV, targetTilt)
                ;[s.scale, s.scaleV] = step(s.scale, s.scaleV, targetScale)

                if (
                    Math.abs(s.lift - targetLift) > 0.0004 ||
                    Math.abs(s.liftV) > 0.0004 ||
                    Math.abs(s.tilt - targetTilt) > 0.00006 ||
                    Math.abs(s.scale - targetScale) > 0.00006
                ) {
                    anyActive = true
                }
            }
            applySprings()
            return anyActive
        }

        function startLoop() {
            rafActive = true
            lastTime = performance.now()
            const tick = () => {
                if (disposed) return
                const now = performance.now()
                const dt = Math.min(0.05, (now - lastTime) / 1000)
                lastTime = now

                let springsActive = false
                if (!prefersReducedMotion) {
                    springsActive = stepSprings(dt)
                }

                if (needsRender || springsActive) {
                    needsRender = false
                    renderer.render(scene, camera)
                }

                if (springsActive) {
                    rafId = requestAnimationFrame(tick)
                } else {
                    rafActive = false
                    rafId = null
                }
            }
            rafId = requestAnimationFrame(tick)
        }

        renderer.render(scene, camera)

        // -----------------------------------------------------------------
        // Pointer interaction (skipped for static renderer)
        // -----------------------------------------------------------------
        const raycaster = new THREE.Raycaster()
        const pointerNDC = new THREE.Vector2()
        let pointerRafPending = false
        let lastPointerEvent: PointerEvent | null = null
        let downInfo: { x: number; y: number; t: number } | null = null

        function computeHover() {
            pointerRafPending = false
            if (!lastPointerEvent || cubeMeshes.length === 0) return
            const rect = mount!.getBoundingClientRect()
            pointerNDC.x = ((lastPointerEvent.clientX - rect.left) / rect.width) * 2 - 1
            pointerNDC.y = -((lastPointerEvent.clientY - rect.top) / rect.height) * 2 + 1
            raycaster.setFromCamera(pointerNDC, camera)
            const hits = raycaster.intersectObjects(cubeMeshes, false)
            if (hits.length > 0) {
                const idx = (hits[0].object as any).userData.cubeIndex
                if (hover) setHovered(idx)
                mount!.style.cursor = cubeGroups[idx].userData.hasLink ? "pointer" : "default"
            } else {
                if (hover) setHovered(-1)
                mount!.style.cursor = "default"
            }
        }

        function onPointerMove(e: PointerEvent) {
            lastPointerEvent = e
            if (!pointerRafPending) {
                pointerRafPending = true
                requestAnimationFrame(computeHover)
            }
        }
        function onPointerLeave() {
            lastPointerEvent = null
            if (hover) setHovered(-1)
            mount!.style.cursor = "default"
        }
        function onPointerDown(e: PointerEvent) {
            downInfo = { x: e.clientX, y: e.clientY, t: performance.now() }
        }
        function raycastAt(clientX: number, clientY: number): number {
            if (cubeMeshes.length === 0) return -1
            const rect = mount!.getBoundingClientRect()
            pointerNDC.x = ((clientX - rect.left) / rect.width) * 2 - 1
            pointerNDC.y = -((clientY - rect.top) / rect.height) * 2 + 1
            raycaster.setFromCamera(pointerNDC, camera)
            const hits = raycaster.intersectObjects(cubeMeshes, false)
            return hits.length > 0 ? (hits[0].object as any).userData.cubeIndex : -1
        }
        function onPointerUp(e: PointerEvent) {
            if (!downInfo) return
            const dx = e.clientX - downInfo.x
            const dy = e.clientY - downInfo.y
            const dt = performance.now() - downInfo.t
            downInfo = null
            if (Math.hypot(dx, dy) > 6 || dt > 600) return
            const idx = raycastAt(e.clientX, e.clientY)
            if (idx >= 0) {
                const link = items[idx]?.link
                if (link) window.open(link, "_blank", "noopener,noreferrer")
            }
        }

        if (!isStatic && !isThumbnail) {
            mount.addEventListener("pointermove", onPointerMove)
            mount.addEventListener("pointerleave", onPointerLeave)
            mount.addEventListener("pointerdown", onPointerDown)
            mount.addEventListener("pointerup", onPointerUp)
        }

        // -----------------------------------------------------------------
        // Resize (read-only ResizeObserver)
        // -----------------------------------------------------------------
        let resizeRaf: number | null = null
        const resizeObserver = new ResizeObserver((entries) => {
            if (resizeRaf) cancelAnimationFrame(resizeRaf)
            resizeRaf = requestAnimationFrame(() => {
                for (const entry of entries) {
                    const w = Math.max(1, Math.round(entry.contentRect.width))
                    const h = Math.max(1, Math.round(entry.contentRect.height))
                    if (w === containerW && h === containerH) continue
                    containerW = w
                    containerH = h
                    renderer.setSize(w, h)
                    camera.aspect = w / h
                    fitCameraToContainer(w, h)
                    camera.updateProjectionMatrix()
                    requestRender()
                }
            })
        })
        resizeObserver.observe(mount)

        // -----------------------------------------------------------------
        // Visibility-based pause
        // -----------------------------------------------------------------
        const intersectionObserver =
            typeof IntersectionObserver !== "undefined"
                ? new IntersectionObserver(
                      (entries) => {
                          for (const e of entries) {
                              if (e.isIntersecting) requestRender()
                          }
                      },
                      { threshold: 0.01 }
                  )
                : null
        intersectionObserver?.observe(mount)

        function onVisibilityChange() {
            if (document.visibilityState === "visible") requestRender()
        }
        document.addEventListener("visibilitychange", onVisibilityChange)

        return () => {
            disposed = true
            if (rafId !== null) cancelAnimationFrame(rafId)
            if (resizeRaf !== null) cancelAnimationFrame(resizeRaf)
            resizeObserver.disconnect()
            intersectionObserver?.disconnect()
            document.removeEventListener("visibilitychange", onVisibilityChange)
            mount.removeEventListener("pointermove", onPointerMove)
            mount.removeEventListener("pointerleave", onPointerLeave)
            mount.removeEventListener("pointerdown", onPointerDown)
            mount.removeEventListener("pointerup", onPointerUp)

            cubeGeo.dispose()
            planeGeo.dispose()
            for (const mat of materialCache.values()) mat.dispose()
            for (const tex of textureCache.values()) tex.dispose()
            pileGroup.traverse((obj: any) => {
                if (obj.isMesh && obj.geometry === planeGeo) obj.material.dispose()
            })
            if (floorMesh) {
                floorMesh.geometry.dispose()
                floorMesh.material.dispose()
            }
            if (groundMesh) {
                groundMesh.geometry.dispose()
                groundMesh.material.map?.dispose()
                groundMesh.material.dispose()
            }
            contactShadowGeo.dispose()
            contactShadowTex.dispose()
            contactShadowMat.dispose()
            reflectionMat?.dispose()
            envRT?.dispose()
            renderer.dispose()
            if (renderer.domElement.parentNode === mount) mount.removeChild(renderer.domElement)
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [
        webglSupported,
        isStatic,
        resolvedLogos,
        cubeColor,
        cornerRadius,
        roughness,
        clearcoat,
        logoScaleDefault,
        spread,
        depth,
        density,
        randomness,
        seed,
        hover,
        hoverLift,
        hoverTilt,
        hoverScale,
        pointerParallax,
        showFloor,
        floorColor,
        transparentBackground,
        backgroundColor,
        cameraDistance,
        cameraElevation,
        lightingIntensity,
        shadowStrength,
        quality,
        mobileScale,
        mobileQuality,
    ])

    const rootStyle: CSSProperties = {
        ...style,
        position: "relative",
        overflow: "hidden",
        background: transparentBackground ? "transparent" : backgroundColor,
    }

    if (!webglSupported) {
        return (
            <div style={rootStyle}>
                <div
                    style={{
                        position: "absolute",
                        inset: 0,
                        display: "flex",
                        flexWrap: "wrap",
                        alignContent: "center",
                        justifyContent: "center",
                        gap: 16,
                        padding: 24,
                        background: backgroundColor,
                    }}
                >
                    {resolvedLogos.map((item, i) => {
                        const content = item.image?.src ? (
                            <img
                                src={item.image.src}
                                alt={item.image.alt || item.name}
                                style={{ width: 56, height: 56, objectFit: "contain" }}
                            />
                        ) : (
                            <div
                                style={{
                                    width: 56,
                                    height: 56,
                                    display: "flex",
                                    alignItems: "center",
                                    justifyContent: "center",
                                    fontFamily: "-apple-system, sans-serif",
                                    fontWeight: 700,
                                    fontSize: 18,
                                    color: "#242017",
                                }}
                            >
                                {item.name.slice(0, 2).toUpperCase()}
                            </div>
                        )
                        const box = (
                            <div
                                style={{
                                    width: 88,
                                    height: 88,
                                    borderRadius: 16,
                                    background: item.colorOverride || cubeColor,
                                    display: "flex",
                                    alignItems: "center",
                                    justifyContent: "center",
                                    boxShadow: "0 8px 18px rgba(0,0,0,0.12)",
                                }}
                            >
                                {content}
                            </div>
                        )
                        return item.link ? (
                            <a
                                key={i}
                                href={item.link}
                                target="_blank"
                                rel="noopener noreferrer"
                                aria-label={item.name}
                            >
                                {box}
                            </a>
                        ) : (
                            <div key={i}>{box}</div>
                        )
                    })}
                </div>
            </div>
        )
    }

    return (
        <div style={rootStyle}>
            <div ref={mountRef} style={{ position: "absolute", inset: 0 }} aria-hidden="true" />
            <ul style={visuallyHidden}>
                {resolvedLogos
                    .filter((item) => item.link)
                    .map((item, i) => (
                        <li key={i}>
                            <a href={item.link} target="_blank" rel="noopener noreferrer">
                                {item.name}
                            </a>
                        </li>
                    ))}
            </ul>
        </div>
    )
}

